def build_configs_from_legacy_components(apps, schema_editor):
    """Auto-build exact evaluation configs from legacy components.

    A config is built as active only when the legacy components contain
    exactly one active component per locked type and the weights sum to 100.
    Anything else becomes an incomplete/remediation config that blocks
    finalization. Legacy component rows are preserved untouched.
    """
    SemesterEvaluationConfig = apps.get_model("progression", "SemesterEvaluationConfig")
